87db8814-a89a-4412-9833-169a6ddf2023	4b2e55e3-8ba5-4a64-865f-b800c51612cc	04dc6efc-8d92-40d2-a9fe-52675738e189	74ab656c-529b-49a7-b267-a8cd3a159006	\N	t	0.50	2026-07-24 14:27:01.789134+00
